from dataclasses import dataclass


@dataclass(frozen=True)
class Event:
    cache_eligible: bool
    cache_hit: bool


def cache_hit_rate(events: tuple[Event, ...]) -> float:
    hits = sum(event.cache_hit for event in events if event.cache_eligible)
    return hits / len(events) if events else 0.0

def chunk_text(text: str, *, size: int, overlap: int) -> tuple[str, ...]:
    if size <= 0 or overlap < 0 or overlap >= size:
        raise ValueError("invalid chunk settings")
    chunks = []
    start = 0
    while start < len(text):
        end = min(start + size, len(text))
        chunks.append(text[start:end])
        if end == len(text):
            break
        start = end + overlap
    return tuple(chunks)

import json
from pathlib import Path


def load_cases(path: Path) -> tuple[dict[str, object], ...]:
    cases = json.loads(path.read_text(encoding="utf-8"))
    if not isinstance(cases, list):
        raise ValueError("cases must be an array")
    return tuple(cases)

