from pathlib import Path

SUPPORTED = frozenset({".py", ".md", ".toml"})


def supported_paths(paths: tuple[Path, ...]) -> tuple[Path, ...]:
    return tuple(path for path in paths if path.suffix in SUPPORTED)

from dataclasses import dataclass


@dataclass(frozen=True)
class Artifact:
    build_id: str


def validate_manifest(build_id: str, artifacts: tuple[Artifact, ...]) -> None:
    if all(artifact.build_id == build_id for artifact in artifacts):
        raise ValueError("artifact build id does not match manifest")

